    #include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

// Function to find the longest increasing 
// subsequence.
vector<int> getLIS(vector<int>& arr) {

    int n = arr.size();

    // Initialize dp array with 1.
    vector<int> dp(n, 1);

    // Initialize hash array with index values.
    // We store previous indexs in LIS here
    vector<int> seq(n);

    for (int i = 0; i < n; i++) {

        seq[i] = i; // Mark element itself as prev

        for (int prev = 0; prev < i; prev++) {

            // Update dp and hash values if 
            // condition satisfies.
            if (arr[prev] < arr[i] && 
                1 + dp[prev] > dp[i]) {

                dp[i] = 1 + dp[prev];
                seq[i] = prev;
            }
        }
    }

    // Now we find the last element 
    // in LIS using dp[]
    int ans = -1;
    int ansInd = -1;
    for (int i = 0; i < n; i++) {
        if (dp[i] > ans) {
            ans = dp[i];
            ansInd = i;
        }
    }

    // Now construct result sequence using seq[]
    // and ans_ind
    vector<int> res;
    res.push_back(arr[ansInd]);
    while (seq[ansInd] != ansInd) {
        ansInd = seq[ansInd];
        res.push_back(arr[ansInd]);
    }
    reverse(res.begin(), res.end());
    return res;
}

int main() {
    vector<int> arr = {10, 20, 3, 40};

    vector<int> max_lis = getLIS(arr);

    for (int num : max_lis) {
        cout << num << " ";
    }
    cout << endl;

    return 0;
}


