    function getLIS(arr) {
    let ret = [];  
    let dp = [];  
    let prv = {}; 
    let N = arr.length;

    // Process array in reverse order
    for (let ix = N - 1; ix >= 0; --ix) {
        let ve = -arr[ix];  

        // Binary search to find insertion point
        let l = 0, r = dp.length;
        while (l < r) {
            let m = l + Math.floor((r - l) / 2);
            if (dp[m][0] < ve) {
                l = m + 1;
            } else {
                r = m;
            }
        }
        let i = l;

        // Default previous index
        let tmp = -1;  

        if (i === dp.length) {
            if (dp.length > 0) {
                tmp = dp[dp.length - 1][1];
            }
            dp.push([ve, ix]);
        } else {
            if (i > 0) {
                tmp = dp[i - 1][1];
            }
            dp[i] = [ve, ix];
        }
        prv[ix] = tmp;
    }

    // Reconstruct the LIS
    let cur = dp[dp.length - 1][1];
    while (cur >= 0) {
        ret.push(arr[cur]);
        cur = prv[cur] !== undefined ? prv[cur] : -1;
    }

    return ret;
}

